<?php require '../database.php';require_admin();$books=$conn->query("SELECT COUNT(*) n FROM books")->fetch_assoc()['n'];$users=$conn->query("SELECT COUNT(*) n FROM users")->fetch_assoc()['n'];$pending=$conn->query("SELECT COUNT(*) n FROM issues WHERE status='Pending'")->fetch_assoc()['n'];$issued=$conn->query("SELECT COUNT(*) n FROM issues WHERE status='Issued'")->fetch_assoc()['n'];?><!doctype html><html><head><title>Admin Dashboard</title><link rel="stylesheet" href="../style.css"></head><body><header><b>Library Admin</b><nav><a href="dashboard.php">Dashboard</a><a href="books.php">Books</a><a href="students.php">Students</a><a href="issues.php">Requests</a><a href="../logout.php">Logout</a></nav></header><main class="container"><h1>Admin Dashboard</h1><div class="grid"><?php foreach(['Total books'=>$books,'Students'=>$users,'Pending requests'=>$pending,'Currently issued'=>$issued] as $label=>$n):?><div class="card"><p><?=e($label)?></p><h2><?=e($n)?></h2></div><?php endforeach;?></div><p>Use the navigation links to manage the library.</p></main></body></html>